gavQ(){return"\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u0627\u062a"},
gavV(){return"\u0623\u062b\u0627\u062b"},
gavR(){return"\u0623\u0632\u064a\u0627\u0621"},
